"use client";
/* Coffee, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Coffee(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("coffee"); }, []);
  return React.createElement("piix-sprite", { "name": "coffee", ...piixAttrs(props) });
}

export default Coffee;
